    billingEmail: {
      type: 'string',
      required: true,
      isEmail: true,
      maxLength: 200
    },

    billingPostcode: {
      type: 'string',
      allowNull: true,
      maxLength: 12
    },

    balanceOwedPence: {
      type: 'number',
      defaultsTo: 0,
      description: 'Outstanding balance across every unpaid invoice, in pence.'
    },

    isOnPaymentPlan: {
      type: 'boolean',
      defaultsTo: false
    },

    registeredAt: {
      type: 'number',
      defaultsTo: 0
