/**
 * User.js
 *
 * Everybody who can sign in. Practice staff get one of the clinical or admin
 * roles; pet owners who use the client portal get `role: 'client'` and a
 * `client` association pointing at the billing record their animals hang off.
 *
 * @docs https://sailsjs.com/docs/concepts/models-and-orm/models
 */

module.exports = {

  attributes: {

    emailAddress: {
      type: 'string',
      required: true,
      unique: true,
      isEmail: true,
      maxLength: 200,
      example: 'sam.okafor@northgatevets.co.uk'
    },

    password: {
      type: 'string',
      required: true,
      description: 'Securely hashed representation of the user\'s login password.',
      protect: true,
      example: '2$28a8eabna301089103-13948134nad'
    },

    fullName: {
      type: 'string',
      required: true,
      maxLength: 120
    },

    jobTitle: {
      type: 'string',
      allowNull: true,
      maxLength: 120,
      description: 'Free text shown in the staff directory, e.g. "Senior Surgeon".'
    },

    role: {
      type: 'string',
      isIn: ['client', 'receptionist', 'nurse', 'veterinarian', 'practice_manager', 'admin'],
      defaultsTo: 'client'
    },

    phone: {
      type: 'string',
      allowNull: true,
      maxLength: 40
    },

    marketingOptIn: {
      type: 'boolean',
      defaultsTo: false
    },

    appointmentRemindersOptIn: {
      type: 'boolean',
      defaultsTo: true
    },

    preferredContactMethod: {
      type: 'string',
      isIn: ['email', 'sms', 'phone'],
      defaultsTo: 'email'
    },

    passwordResetToken: {
      type: 'string',
      allowNull: true,
      protect: true
    },

    passwordResetTokenExpiresAt: {
      type: 'number',
      defaultsTo: 0
    },

    twoFactorSecret: {
      type: 'string',
      allowNull: true,
      protect: true,
      description: 'Base32 TOTP seed. Only set for staff accounts.'
    },

    isAccountLocked: {
      type: 'boolean',
      defaultsTo: false
    },

    lastSeenAt: {
      type: 'number',
      defaultsTo: 0
    },

    //  ╔═╗╔═╗╔═╗╔═╗╔═╗╦╔═╗╔╦╗╦╔═╗╔╗╔╔═╗
    //  ╠═╣╚═╗╚═╗║ ║║  ║╠═╣ ║ ║║ ║║║║╚═╗
    //  ╩ ╩╚═╝╚═╝╚═╝╚═╝╩╩ ╩ ╩ ╩╚═╝╝╚╝╚═╝

    clinic: {
      model: 'clinic',
      description: 'The site this user is based at. Staff only ever work at one site.'
    },

    client: {
      model: 'client',
      description: 'Only set for portal users -- the billing record they can see.'
    }

  },

  customToJSON: function () {
    // Never let credential material leave the building, whichever endpoint is
    // serialising the record.
    return _.omit(this, ['password', 'passwordResetToken', 'twoFactorSecret']);
  }

};

