extraFiles.api/policies/is-clinic-staff.js:
/**
 * is-clinic-staff.js
 *
 * Keeps portal users (pet owners) out of the internal screens. Assumes
 * `isLoggedIn` has already run and populated `req.me`.
 */

var STAFF_ROLES = ['receptionist', 'nurse', 'veterinarian', 'practice_manager', 'admin'];

module.exports = function (req, res, proceed) {

  if (!req.me) {
    return res.unauthorized();
  }

  if (!_.includes(STAFF_ROLES, req.me.role)) {
    return res.forbidden('This area is for practice staff only.');
  }

  return proceed();

};

extraFiles.api/policies/is-logged-in.js:
/**
 * is-logged-in.js
 *
 * Turns the signed-in user's id in the session into a full record on `req.me`
 * so that actions and downstream policies do not each have to look it up.
 *
 * @docs https://sailsjs.com/docs/concepts/policies
 */

module.exports = async function (req, res, proceed) {

  if (!req.session.userId) {
    return res.unauthorized();
  }

  var loggedInUser = await User.findOne({ id: req.session.userId }).populate('clinic');

  if (!loggedInUser) {
    // Session points at a user who has since been deleted. Bin the session
    // rather than leaving the browser in a half-signed-in state.
    delete req.session.userId;
    return res.unauthorized();
  }

  if (loggedInUser.isAccountLocked) {
    return res.forbidden('Your account has been locked. Please speak to the practice manager.');
  }

  req.me = loggedInUser;

  // Cheap presence tracking for the "who is on the system" widget.
  if (Date.now() - loggedInUser.lastSeenAt > 60 * 1000) {
    await User.updateOne({ id: loggedInUser.id }).set({ lastSeenAt: Date.now() });
  }

  return proceed();

};

